/** Explicit original-attempt schema21 continuation backup/restore only. No I/O on import. */
import {readFile} from 'node:fs/promises'
import {resolve} from 'node:path'
import type {WorkspaceConnection,WorkspaceSql} from '../../packages/neuvetra-database/src/workspace'
import {createPostgresConnection} from '../../packages/neuvetra-database/src/hosted'
import type {Bundle} from './m78-backup'
import {restoreLocalBundle,validateBundle} from './m78-restore'
import {connectOperator} from './m77-common'
import {EXCLUSION,hostedDumpEnvironment,parseOperatorJson,exclusiveJournal,applicationRestoreInventory,compareHostedApplicationRestore,hostedSourcePins,type DurableWriter} from './m78-hosted-database'
import {canonicalReceipts,inventory,content,sameExactInventory,sameContent,validateInventory,validateContent,runtimeSafe,check,digest,sha,hash,PROJECT,REVIEWED_MIGRATION_SHA256,DEFAULT_SQL} from './m78-inventory'
export const CONTINUATION_PROFILE='neuvetra.m78.continuation21-snapshot.v1' as const
export const FIXED={archive:'.superpowers/m78-continuation21-20260922.dpapi',backupJournal:'.superpowers/m78-continuation21-20260922-backup.jsonl',restoreJournal:'.superpowers/m78-continuation21-20260922-hosted-restore.jsonl',localJournal:'.superpowers/m78-continuation21-20260922-local-restore.jsonl',database:'m78_ops_continuation_20260922',journal:'.superpowers/m78-hosted-journey.jsonl',journalSha256:'d3301eb226c0cae4428c1e20cde4e2afdcf572b622e96d690cc8c262d6e44058',observation:'.superpowers/m78-timeout-observation.json',observationSha256:'995f91359f1b5ce38ad5b2f1324194c24c222a73ef2f2108944b6a4bf1797d67',review:'evaluations/research-qa/m78-timeout-actual-independent-result.json',reviewSha256:'3147cea316a075ad7e114052d007efeda5202462282b678175531d4a5c056d00',versionId:'3e45de5d-d312-4a22-8418-35cb740a3a12',versionSha256:'977fdd9d6a5cffb07bea34ff3bee2afaadfe3cf120440cc148a2ed45501bee6e'} as const
export const PROVENANCE={originalJournalSha256:FIXED.journalSha256,observationSha256:FIXED.observationSha256,independentReviewSha256:FIXED.reviewSha256,versionId:FIXED.versionId,versionSha256:FIXED.versionSha256} as const
export interface ContinuationSnapshot extends Omit<Bundle,'profile'>{profile:typeof CONTINUATION_PROFILE;source:{transport:'fixed-project-operator-verify-full';database:'postgres';providerRecoveryExcluded:true};provenance:typeof PROVENANCE}
export interface ContinuationGuard {observation:any;provenance:typeof PROVENANCE}
export async function loadContinuationGuard(read:(p:string)=>Promise<Uint8Array>=readFile):Promise<ContinuationGuard>{
 const journal=await read(FIXED.journal),observed=await read(FIXED.observation),review=await read(FIXED.review);check(sha(journal)===FIXED.journalSha256&&sha(observed)===FIXED.observationSha256&&sha(review)===FIXED.reviewSha256,'Original outcome evidence changed')
 const o=parseOperatorJson(Buffer.from(observed).toString('utf8'),32*1024*1024)as any;validateGuardObservation(o);return {observation:o,provenance:PROVENANCE}
}
export function validateGuardObservation(o:any){
 check(o.status==='m78_timed_out_save_confirmed_committed'&&o.project===PROJECT&&o.readOnly===true&&o.applicationWrites===0&&o.journalSha256===FIXED.journalSha256&&o.intentSequence===63&&o.version?.id===FIXED.versionId&&o.version.version_sha256===FIXED.versionSha256,'Exact original committed save required');validateInventory(o.inventory);validateContent(o.content);check(o.inventory.tables.length===121&&o.content.schemaVersion===21,'Exact21 observation required')
 for(const table of ['scope1_heads','scope1_versions','scope1_requests','scope1_audit'])check(o.inventory.tables.find((t:any)=>t.name===table)?.count===1,'Only initial inventory allowed')
 for(const table of ['scope1_statements','scope1_reviews','scope1_reports','scope1_process_discoveries'])check(o.inventory.tables.find((t:any)=>t.name===table)?.count===0,'No continuation may already exist')
}
export async function continuationSourcePins(){return [...await hostedSourcePins(),...await Promise.all(['tools/staging/m78-continuation-backup.ts','tools/staging/m78-continuation-backup.test.ts'].map(async path=>({path,sha256:sha(await readFile(path))})))].sort((a,b)=>a.path.localeCompare(b.path))}
async function assertHosted(tx:WorkspaceSql){const r=(await tx.query<{name:string;actor:string;readonly:string}>("select current_database() name,current_user actor,current_setting('transaction_read_only') readonly")).rows[0];check(r?.name==='postgres'&&r.actor==='postgres'&&r.readonly==='on','Fixed readonly hosted operator required')}
export async function createContinuationSnapshot(db:WorkspaceConnection,pgDump:string,rawOperatorUrl:string,guard:ContinuationGuard):Promise<ContinuationSnapshot>{
 validateGuardObservation(guard.observation);check(hash(guard.provenance)===hash(PROVENANCE),'Guard provenance changed');
 const env=hostedDumpEnvironment(rawOperatorUrl);
 return db.transaction(async tx=>{
  await tx.exec('set transaction isolation level repeatable read read only');await assertHosted(tx);await canonicalReceipts(tx,21);await runtimeSafe(tx);
  const snapshot=(await tx.query<{snapshot:string}>('select pg_export_snapshot() snapshot')).rows[0]!.snapshot,before=await inventory(tx),bytes=await content(tx,21);
  sameExactInventory(guard.observation.inventory,before);sameContent(guard.observation.content,bytes);
  check(before.dependencies.every(d=>d.schema==='auth'&&d.relation==='users'),'External dependency unsupported');
  const refs=(await tx.query<{table_name:string;column_name:string}>("select c.relname table_name,a.attname column_name from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum=k.conkey[1] where n.nspname='neuvetra'and k.contype='f'and k.confrelid='auth.users'::regclass and cardinality(k.conkey)=1 order by 1,2")).rows;
  check(refs.length>0&&refs.every(r=>/^[a-z][a-z0-9_]*$/.test(r.table_name)&&/^[a-z][a-z0-9_]*$/.test(r.column_name)));
  const subjects=(await tx.query<{id:string}>('select distinct id from ('+refs.map(r=>`select ${r.column_name} id from neuvetra.${r.table_name}`).join(' union all ')+')u where id is not null order by id')).rows.map(r=>r.id),uid=(await tx.query<{definition:string}>("select pg_get_functiondef('auth.uid()'::regprocedure) definition")).rows[0]!.definition;
  check(subjects.every(id=>/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)),'Auth subject UUID required');
  const child=Bun.spawn([pgDump,'--format=custom','--no-password','--schema=neuvetra','--snapshot='+snapshot],{env,stdout:'pipe',stderr:'pipe'});
  const [dump,,code]=await Promise.all([new Response(child.stdout).arrayBuffer(),new Response(child.stderr).text(),child.exited]);check(code===0&&dump.byteLength>16,'Application dump failed');sameExactInventory(before,await inventory(tx));
  return {profile:CONTINUATION_PROFILE,source:{transport:'fixed-project-operator-verify-full',database:'postgres',providerRecoveryExcluded:true},provenance:guard.provenance,project:PROJECT,createdAt:new Date().toISOString(),schemaVersion:21,migrationSha256:REVIEWED_MIGRATION_SHA256,inventory:before,content:bytes,dependencies:{authUserIds:subjects,authUidDefinition:uid,providerRecovery:EXCLUSION},dumpSha256:sha(new Uint8Array(dump)),dumpBase64:Buffer.from(dump).toString('base64')};
 });
}
export function continuationPayload(s:ContinuationSnapshot,expectedSha:string):Bundle{
 check(sha(JSON.stringify(s))===expectedSha&&s.profile===CONTINUATION_PROFILE&&s.project===PROJECT&&s.schemaVersion===21&&s.migrationSha256===REVIEWED_MIGRATION_SHA256&&hash(s.provenance)===hash(PROVENANCE),'Exact continuation21 snapshot required')
 check(s.source.transport==='fixed-project-operator-verify-full'&&s.source.database==='postgres'&&s.source.providerRecoveryExcluded===true&&s.dependencies.providerRecovery===EXCLUSION,'Recovery boundary changed');validateInventory(s.inventory);validateContent(s.content);check(s.inventory.tables.length===121&&s.content.schemaVersion===21,'Exact21 application required')
 const {source:_,provenance:__,profile:___,...body}=s;const bundle:Bundle={...body,profile:'neuvetra.m78.local-application-bundle.v1',inventory:applicationRestoreInventory(s.inventory)};validateBundle(bundle,sha(JSON.stringify(bundle)));return bundle
}
export function validateArguments(mode:string,args:string[]){
 if(mode==='backup'){check(args.length===3&&args[1]===FIXED.archive&&args[2]===FIXED.backupJournal&&!!args[0],'Fixed backup outputs required');return}
 check(mode==='restore'&&args.length===7&&args[0]===FIXED.archive&&digest(args[1])&&digest(args[2])&&!!args[3]&&args[4]===FIXED.database&&args[5]===FIXED.localJournal&&args[6]===FIXED.restoreJournal,'Fixed fresh restore only')
}
export function verifyContinuationBackupJournal(text:string,archiveSha:string,snapshotSha:string){
 const lines=text.trimEnd().split('\n');check(lines.length===2&&text.endsWith('\n'),'Original closed backup journal required');const [start,end]=lines.map(x=>parseOperatorJson(x,32*1024*1024)as any);
 check(start.status==='m78_continuation21_backup_started'&&end.status==='m78_continuation21_encrypted_backup'&&start.project===PROJECT&&end.project===PROJECT&&end.profile===CONTINUATION_PROFILE&&end.schemaVersion===21&&end.migrationSha256===REVIEWED_MIGRATION_SHA256&&end.archiveSha256===archiveSha&&end.snapshotSha256===snapshotSha&&hash(start.provenance)===hash(PROVENANCE)&&hash(end.provenance)===hash(PROVENANCE),'Original archive journal identity changed');
 check(Number.isFinite(Date.parse(start.createdAt))&&Number.isFinite(Date.parse(end.createdAt))&&Date.parse(start.createdAt)<=Date.parse(end.createdAt),'Backup journal chronology');return end;
}
export async function restoreContinuation(s:ContinuationSnapshot,snapshotSha:string,archiveSha:string,pgRestore:string){
 check(digest(archiveSha));const guard=await loadContinuationGuard();sameExactInventory(guard.observation.inventory,s.inventory);sameContent(guard.observation.content,s.content);const bundle=continuationPayload(s,snapshotSha),bundleSha=sha(JSON.stringify(bundle)),admin=createPostgresConnection('postgres://supabase_admin@127.0.0.1:55472/postgres',{tls:false,maxConnections:1});
 try{const before=(await admin.query(DEFAULT_SQL)).rows;check(!before.some(r=>r.schema==='*'||r.schema==='neuvetra'),'Local application defaults forbidden');const receipt=await restoreLocalBundle(bundle,bundleSha,pgRestore,FIXED.database,FIXED.localJournal);check(hash(before)===hash((await admin.query(DEFAULT_SQL)).rows),'Local defaults changed');return {...receipt,status:'m78_continuation21_restored_locally',sourceProfile:CONTINUATION_PROFILE,archiveSha256:archiveSha,snapshotSha256:snapshotSha,transferBundleSha256:bundleSha,provenance:PROVENANCE,sourceFullInventory:s.inventory,applicationRestoreComparison:compareHostedApplicationRestore(s.inventory,receipt.inventory),localDefaultAclsPrerequisitesUnchanged:true}}
 finally{await admin.close()}
}
async function unseal(archive:string){const child=Bun.spawn(['powershell.exe','-NoProfile','-NonInteractive','-Command',"Add-Type -AssemblyName System.Security; $p=[Console]::In.ReadToEnd(); $b=[Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($p),$null,[Security.Cryptography.DataProtectionScope]::CurrentUser); [Console]::Out.Write([Text.Encoding]::UTF8.GetString($b))"],{stdin:'pipe',stdout:'pipe',stderr:'pipe'});await child.stdin.write(resolve(archive));await child.stdin.end();const [text,,code]=await Promise.all([new Response(child.stdout).text(),new Response(child.stderr).text(),child.exited]);check(code===0,'Archive unprotect refused');return parseOperatorJson(text,256*1024*1024)as ContinuationSnapshot}
async function main(){let db:WorkspaceConnection|undefined,journal:DurableWriter|undefined,stage='admission';try{
 const [mode,...args]=process.argv.slice(2);if(mode==='pins'){check(args.length===0);console.log(JSON.stringify(await continuationSourcePins()));return}validateArguments(mode!,args);const guard=await loadContinuationGuard();
 if(mode==='backup'){
  const [pgDump,archive,journalPath]=args;check(!await Bun.file(archive!).exists(),'Archive already exists');const input=parseOperatorJson(await Bun.stdin.text(),65536)as any;check(Object.keys(input).sort().join(',')==='operatorDatabaseUrl,operatorId'&&input.operatorId==='/root');hostedDumpEnvironment(input.operatorDatabaseUrl);
  journal=await exclusiveJournal(journalPath!);await journal.append({status:'m78_continuation21_backup_started',createdAt:new Date().toISOString(),project:PROJECT,provenance:PROVENANCE});stage='snapshot';db=await connectOperator(input.operatorDatabaseUrl);const s=await createContinuationSnapshot(db,pgDump!,input.operatorDatabaseUrl,guard),bytes=JSON.stringify(s);stage='seal';
  const child=Bun.spawn(['powershell.exe','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',resolve('tools/staging/m77-seal-backup.ps1'),'-ArchivePath',resolve(archive!)],{stdin:'pipe',stdout:'pipe',stderr:'pipe'});await child.stdin.write(bytes);await child.stdin.end();const [out,,code]=await Promise.all([new Response(child.stdout).text(),new Response(child.stderr).text(),child.exited]);check(code===0&&JSON.parse(out).status==='m77_bundle_sealed','DPAPI seal refused');
  await journal.append({status:'m78_continuation21_encrypted_backup',profile:CONTINUATION_PROFILE,createdAt:s.createdAt,project:PROJECT,schemaVersion:21,migrationSha256:REVIEWED_MIGRATION_SHA256,archiveSha256:sha(await readFile(archive!)),snapshotSha256:sha(bytes),dumpSha256:s.dumpSha256,inventory:s.inventory,content:s.content,provenance:PROVENANCE,protection:'DPAPI CurrentUser',providerRecoveryExcluded:true});
 }else{const [archive,archiveSha,snapshotSha,pgRestore]=args;check(sha(await readFile(archive!))===archiveSha,'Archive bytes changed');const backupBytes=await readFile(FIXED.backupJournal),backup=verifyContinuationBackupJournal(backupBytes.toString('utf8'),archiveSha!,snapshotSha!);sameExactInventory(guard.observation.inventory,backup.inventory);sameContent(guard.observation.content,backup.content);journal=await exclusiveJournal(FIXED.restoreJournal);await journal.append({status:'m78_continuation21_restore_started',createdAt:new Date().toISOString(),project:PROJECT,database:FIXED.database,archiveSha256:archiveSha,snapshotSha256:snapshotSha,originalBackupJournalSha256:sha(backupBytes)});stage='unprotect';const s=await unseal(archive!);check(s.createdAt===backup.createdAt&&s.dumpSha256===backup.dumpSha256,'Original backup snapshot changed');stage='restore_fresh';await journal.append({...await restoreContinuation(s,snapshotSha!,archiveSha!,pgRestore!),originalBackupJournalSha256:sha(backupBytes)})}
 console.log(JSON.stringify({status:'m78_continuation21_operation_completed',mode}));
 }catch{try{await journal?.append({status:'m78_continuation21_failed_verify_before_retry',stage,project:PROJECT})}catch{}console.log(JSON.stringify({status:'m78_continuation21_failed_verify_before_retry',stage}));process.exitCode=1}finally{await journal?.close();await db?.close()}}
if(import.meta.main)await main()

import {test,expect} from 'bun:test'
import {readFile} from 'node:fs/promises'
import {FIXED,PROVENANCE,CONTINUATION_PROFILE,validateArguments,validateGuardObservation,continuationPayload,loadContinuationGuard,continuationSourcePins,verifyContinuationBackupJournal} from './m78-continuation-backup'
import {EXCLUSION} from './m78-hosted-database'
import {sha,hash,PROJECT,REVIEWED_MIGRATION_SHA256,NEW_TABLES} from './m78-inventory'
function fixture(){
 const h='a'.repeat(64),tables=[{name:'schema_migrations',count:21,sha256:h,rowHashes:Array(21).fill(h)},...Array.from({length:112},(_,i)=>({name:'fixture_'+i,count:0,sha256:h,rowHashes:[]})),...NEW_TABLES.map(name=>({name,count:['scope1_heads','scope1_versions','scope1_requests','scope1_audit'].includes(name)?1:0,sha256:h,rowHashes:['scope1_heads','scope1_versions','scope1_requests','scope1_audit'].includes(name)?[h]:[]}))]
 const inventory={tables,metadata:{},catalogRowHashes:{},functions:[],tableObjects:[],sequences:[],roles:[{rolname:'postgres'}],memberships:[],dependencies:[],defaultAcls:[{owner:'postgres',schema:'public',kind:'r',acl:'{}'}]},content={profile:'neuvetra.m78.recovery-content.v1',schemaVersion:21,entries:[],sha256:hash([])}
 const observation={status:'m78_timed_out_save_confirmed_committed',project:PROJECT,readOnly:true,applicationWrites:0,journalSha256:FIXED.journalSha256,intentSequence:63,version:{id:FIXED.versionId,version_sha256:FIXED.versionSha256},inventory,content},dump=Buffer.from('fictional custom archive bytes only')
 const snapshot:any={profile:CONTINUATION_PROFILE,project:PROJECT,createdAt:'2026-09-22T17:00:00.000Z',schemaVersion:21,migrationSha256:REVIEWED_MIGRATION_SHA256,source:{transport:'fixed-project-operator-verify-full',database:'postgres',providerRecoveryExcluded:true},provenance:PROVENANCE,inventory,content,dependencies:{authUserIds:[],authUidDefinition:'fictional',providerRecovery:EXCLUSION},dumpSha256:sha(dump),dumpBase64:dump.toString('base64')}
 return {observation,snapshot}
}
test('fixed backup/restore namespace refuses upgrade, alternate target, output and extra args',()=>{
 const backup=['pg_dump',FIXED.archive,FIXED.backupJournal],restore=[FIXED.archive,'a'.repeat(64),'b'.repeat(64),'pg_restore',FIXED.database,FIXED.localJournal,FIXED.restoreJournal];expect(()=>validateArguments('backup',backup)).not.toThrow();expect(()=>validateArguments('restore',restore)).not.toThrow()
 for(const mode of ['upgrade','retry','other'])expect(()=>validateArguments(mode,backup)).toThrow()
 for(const index of [1,2]){const v=[...backup];v[index]='elsewhere';expect(()=>validateArguments('backup',v)).toThrow()}
 for(const index of [0,1,2,4,5,6]){const v=[...restore];v[index]='elsewhere';expect(()=>validateArguments('restore',v)).toThrow()}
 expect(()=>validateArguments('backup',[...backup,'extra'])).toThrow()
})
test('original single committed inventory and exact provenance are required, no later continuation admitted',()=>{
 const {observation:o}=fixture();expect(()=>validateGuardObservation(o)).not.toThrow()
 for(const patch of [{status:'failed'},{readOnly:false},{applicationWrites:1},{journalSha256:'b'.repeat(64)},{intentSequence:62},{version:{id:FIXED.versionId,version_sha256:'b'.repeat(64)}}])expect(()=>validateGuardObservation({...o,...patch})).toThrow()
 const changed=structuredClone(o);changed.inventory.tables.find(t=>t.name==='scope1_reports')!.count=1;changed.inventory.tables.find(t=>t.name==='scope1_reports')!.rowHashes=['a'.repeat(64)];expect(()=>validateGuardObservation(changed)).toThrow()
})
test('21-only transfer preserves full source, explicitly projects only unrelated defaults and validates dump',()=>{
 const {snapshot:s}=fixture(),before=JSON.stringify(s),b=continuationPayload(s,sha(before));expect(JSON.stringify(s)).toBe(before);expect(b.schemaVersion).toBe(21);expect(b.inventory.defaultAcls).toEqual([]);expect(s.inventory.defaultAcls).toHaveLength(1);expect(b.content).toEqual(s.content)
 for(const patch of [{schemaVersion:20},{migrationSha256:null},{profile:'old'},{provenance:{...PROVENANCE,versionSha256:'b'.repeat(64)}},{dumpSha256:'b'.repeat(64)}]){const changed={...s,...patch};expect(()=>continuationPayload(changed,sha(JSON.stringify(changed)))).toThrow()}
 for(const schema of ['*','neuvetra','unknown']){const changed=structuredClone(s);changed.inventory.defaultAcls[0].schema=schema;expect(()=>continuationPayload(changed,sha(JSON.stringify(changed)))).toThrow()}
 expect(()=>continuationPayload(s,'0'.repeat(64))).toThrow()
})
test('changed private guard bytes refuse before any database action; public source map is complete current bytes',async()=>{
 await expect(loadContinuationGuard(async()=>Buffer.from('{}'))).rejects.toThrow('Original outcome evidence changed')
 const pins=await continuationSourcePins();expect(pins).toHaveLength(117);expect(new Set(pins.map(p=>p.path)).size).toBe(117);for(const pin of pins)expect(sha(await readFile(pin.path))).toBe(pin.sha256)
 expect(pins.some(p=>p.path==='tools/staging/m77-seal-backup.ps1')).toBe(true);expect(pins.filter(p=>p.path.includes('/migrations/'))).toHaveLength(21)
})
test('restore binds original closed backup events and refuses replacement outcomes or chronology',()=>{
 const start={status:'m78_continuation21_backup_started',project:PROJECT,createdAt:'2026-09-22T17:00:00.000Z',provenance:PROVENANCE},end={status:'m78_continuation21_encrypted_backup',project:PROJECT,profile:CONTINUATION_PROFILE,schemaVersion:21,migrationSha256:REVIEWED_MIGRATION_SHA256,archiveSha256:'a'.repeat(64),snapshotSha256:'b'.repeat(64),createdAt:'2026-09-22T17:01:00.000Z',provenance:PROVENANCE};const text=(a:any,b:any)=>JSON.stringify(a)+'\n'+JSON.stringify(b)+'\n';expect(verifyContinuationBackupJournal(text(start,end),end.archiveSha256,end.snapshotSha256)).toEqual(end)
 for(const patch of [{schemaVersion:20},{status:'failed'},{archiveSha256:'c'.repeat(64)},{snapshotSha256:'c'.repeat(64)},{createdAt:'2026-09-22T16:59:00.000Z'},{provenance:{...PROVENANCE,versionId:'other'}}])expect(()=>verifyContinuationBackupJournal(text(start,{...end,...patch}),end.archiveSha256,end.snapshotSha256)).toThrow()
 expect(()=>verifyContinuationBackupJournal(JSON.stringify(end)+'\n',end.archiveSha256,end.snapshotSha256)).toThrow();expect(()=>verifyContinuationBackupJournal(text(start,end)+'{}\n',end.archiveSha256,end.snapshotSha256)).toThrow()
})

param(
  [Parameter(Mandatory=$true)][ValidateSet('backup')][string]$Mode,
  [Parameter(Mandatory=$true)][string[]]$OperationArguments
)
$ErrorActionPreference='Stop'
try {
  $workspace=[IO.Path]::GetFullPath('C:/Users/nimab/.codex/worktrees/4441/Neuvetra')
  $scriptFull=Join-Path $workspace 'tools/staging/m78-continuation-backup.ts'
  if($Mode -cne 'backup' -or $OperationArguments.Count -ne 3){throw 'argument count'}
  $values=@()
  foreach($line in [IO.File]::ReadAllLines('C:/Users/nimab/Neuvetra/env.json.txt')){
    if($line -match '^\s*(?:export\s+)?DATABASE_URL\s*=\s*(.*?)\s*$'){
      $value=$Matches[1]
      if($value.StartsWith('"')){$value=ConvertFrom-Json $value}elseif($value.StartsWith("'") -and $value.EndsWith("'")){$value=$value.Substring(1,$value.Length-2)}
      $values+=$value
    }elseif($line -match '^\s*"DATABASE_URL"\s*:\s*("(?:[^"\\]|\\.)*")\s*,?\s*$'){$values+=(ConvertFrom-Json $Matches[1])}
  }
  if($values.Count -ne 1){throw 'connection selection'}
  $payload=@{operatorDatabaseUrl=[string]$values[0];operatorId='/root'} | ConvertTo-Json -Compress
  $start=[Diagnostics.ProcessStartInfo]::new()
  $start.FileName='C:/Users/nimab/.bun/bin/bun.exe'
  $start.WorkingDirectory=$workspace
  $start.ArgumentList.Add('run');$start.ArgumentList.Add($scriptFull);$start.ArgumentList.Add($Mode)
  foreach($argument in $OperationArguments){$start.ArgumentList.Add($argument)}
  $start.UseShellExecute=$false;$start.CreateNoWindow=$true
  $start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
  $process=[Diagnostics.Process]::Start($start)
  $process.StandardInput.Write($payload);$process.StandardInput.Close()
  $output=$process.StandardOutput.ReadToEndAsync();$errors=$process.StandardError.ReadToEndAsync()
  $process.WaitForExit()
  Write-Output $output.Result
  if($process.ExitCode -ne 0){Write-Output 'M78 private database operation failed; sensitive diagnostics withheld.';exit 1}
}catch{Write-Output 'M78 private database operation unavailable; sensitive diagnostics withheld.';exit 1}
